import React from 'react';

import type { CSSObject } from '@emotion/react';

import { StyledHeading } from './Heading.styles';

export type HeadingSize = 'Hero' | 'H1' | 'H2' | 'H3' | 'H4' | 'H5';
export type TextAlignment = 'left' | 'center' | 'right';

export interface HeadingProps extends Omit<
  React.HTMLAttributes<HTMLHeadingElement>,
  'color'
> {
  size?: HeadingSize;
  foreground?: boolean | 'true' | 'false';
  alignment?: TextAlignment;
  selectable?: boolean | 'true' | 'false';
  css?: CSSObject;
}

const headingTag: Record<HeadingSize, keyof JSX.IntrinsicElements> = {
  Hero: 'h1',
  H1: 'h1',
  H2: 'h2',
  H3: 'h3',
  H4: 'h4',
  H5: 'h5',
};

const toBoolean = (
  value: boolean | 'true' | 'false' | undefined,
  fallback: boolean,
) => (value === undefined ? fallback : value === true || value === 'true');

export const Heading = React.forwardRef<HTMLHeadingElement, HeadingProps>(
  (
    {
      size = 'H1',
      foreground = false,
      alignment = 'left',
      selectable = true,
      css,
      ...props
    },
    forwardedRef,
  ) => (
    <StyledHeading
      {...props}
      as={headingTag[size]}
      ref={forwardedRef}
      $alignment={alignment}
      $css={css}
      $foreground={toBoolean(foreground, false)}
      $selectable={toBoolean(selectable, true)}
      $size={size}
    />
  ),
);

Heading.displayName = 'Heading';
